INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 20, 'theory', 'Quiz: closures and iterators');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 0, 'Which trait does a closure that returns the captured String (move || s) have?', '["FnOnce: it can be called only once", "Fn", "FnMut", "All three"]', 0, 'A closure that consumes a captured value can be called only once: after that the value is given away. Fn and FnMut belong to closures that only read or change the environment.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 1, 'What does the chain v.iter().map(|x| x * 2).filter(|x| x > 4) do without a consumer at the end?', '["Computes all the values and throws them away", "A compile error", "Computes nothing: it only builds a lazy pipeline", "Creates a new vector"]', 2, 'Adapters are lazy. A consumer starts the work: sum, collect, count, for. The compiler warns about an unused iterator.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 2, 'What does the word move before a closure mean?', '["The closure moves to another function", "The closure becomes FnOnce", "The closure runs in another thread", "The closure takes the captured variables into ownership instead of borrowing them"]', 3, 'move changes the way of capturing: the values go into the closure. This is needed so that the closure can outlive the function or go to a thread.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 3, 'Why do you have to write **x or |&&x| in filter(|x| ...) over v.iter()?', '["It is a quirk of the syntax", "iter() yields &T, and filter passes one more reference to the element, giving &&T", "Because x is a function pointer", "Fn requires it"]', 1, 'filter must not take the element away, so it gives &Item, and Item for iter() is already a reference. The pattern |&&x| takes both references apart at once.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 4, 'Why does an adapter chain run as fast as a hand-written loop?', '["Because the compiler runs it on separate threads", "Because the result is cached", "Because each adapter is a struct with a known type, and the closure calls are inlined into one loop", "It is not true: the chain is slower"]', 2, 'There are no intermediate lists or indirect calls: the compiler sees the whole chain and merges it, and often vectorizes the sum.');
